            print("STATUS: UP")
        else:
            print("STATUS: DOWN")
        print(f"HTTP {status}")
        if body:
            print(f"BODY: {body}")
except Exception as e:
    print("STATUS: DOWN")
    print(f"ERROR: {type(e).__name__}: {e}")
